      <DialogTrigger render={<Button size="sm" />}>
        <Plus data-icon="inline-start" className="size-4" />
        New tryout
      \[REDACTED:secret.entropy]>
      \[REDACTED:secret.entropy] className="sm:max-w-lg">
        <form onSubmit={handleSubmit}>
          \[REDACTED:secret.entropy]>
            \[REDACTED:secret.entropy]>New agent tryout\[REDACTED:secret.entropy]>
            \[REDACTED:secret.entropy]>
              Pick a task, paste your real input, and watch an agent do the
              work. Runs in an isolated sandbox on your workspace provider keys.
            \[REDACTED:secret.entropy]>
          \[REDACTED:secret.entropy]>
          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="size-6 animate-spin text-muted-foreground" />
            </div>
          ) : (
            <div className="space-y-4 py-2 max-h-[60vh] overflow-y-auto">
              <div>
                <label className="mb-1.5 block text-sm font-medium">Task</label>
                <select
                  value={templateSlug}
                  onChange={(e) => setTemplateSlug(e.target.value)}
                  className={inputClass}
                >
                  {templates.map((item) => (
                    <option key={item.slug} value={item.slug}>
                      {item.name}
                    </option>
                  ))}
                </select>
                {template ? (
                  <p className="mt-1.5 text-xs text-muted-foreground">
                    {template.description} Up to{" "}
                    {Math.round(template.max_duration_seconds / 60)} min, capped
                    at ${template.max_cost_usd.toFixed(2)}.
                  </p>
                ) : null}
              </div>
              {Object.entries(properties).map(([field, spec]) => (
                <div key={field}>
                  <label className="mb-1.5 block text-sm font-medium">
                    {fieldLabel(field)}
                    {required.has(field) ? null : (
                      <span className="font-normal text-muted-foreground">
                        {" "}
                        (optional)
                      </span>
                    )}
                  </label>
                  {spec.type === "string" ? (
                    <textarea
                      value={fieldValues[field] ?? ""}
                      onChange={(e) =>
                        setFieldValues((current) => ({
                          ...current,
                          [field]: e.target.value,
                        }))
                      }
                      rows={required.has(field) ? 5 : 2}
                      className={`${inputClass} resize-y`}
                    />
                  ) : (
                    <input
                      type="number"
                      value={fieldValues[field] ?? ""}
                      min={spec.minimum}
                      max={spec.maximum}
                      onChange={(e) =>
                        setFieldValues((current) => ({
                          ...current,
                          [field]: e.target.value,
                        }))
                      }
                      className={inputClass}
                    />
                  )}
                </div>
              ))}
            </div>
          )}
          \[REDACTED:secret.entropy]>
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={submitting}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={submitting || loading || !template}>
              {submitting ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                "Launch tryout"
              )}
            </Button>
          \[REDACTED:secret.entropy]>
        </form>
      \[REDACTED:secret.entropy]>
    </Dialog>
  );
}

function fieldLabel(field: string): string {
  const spaced = field.replaceAll("_", " ");
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}
