            </div>
            {mode === "explicit" ? (
              <>
                <div>
                  <label className="mb-1.5 block text-sm font-medium">
                    Provider
                  </label>
                  <select
                    value={provider}
                    onChange={(e) => setProvider(e.target.value)}
                    className={inputClass}
                  >
                    {PROVIDERS.map((key) => (
                      <option key={key} value={key}>
                        {key}
                      </option>
