                    className={inputClass}
                  />
                </div>
              </>
            ) : null}
          </div>
          \[REDACTED:secret.entropy]>
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
              disabled={submitting}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={submitting}>
              {submitting ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                "Rerun"
